import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·25","description":"易小帖 - 卷五·25","frontmatter":{"title":"卷五·25","description":"易小帖 - 卷五·25"},"headers":[],"relativePath":"classics/yixiaotie/147.md","filePath":"classics/yixiaotie/147.md"}'),o={name:"classics/yixiaotie/147.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·25",tabindex:"-1"},[r("卷五·25 "),e("a",{class:"header-anchor",href:"#卷五·25","aria-label":"Permalink to “卷五·25”"},"​")],-1),e("p",null,"答：善哉問也。但佔物之法，以遇卦為主。遇卦有物，則不必更佔之卦。龜與蠃，究之卦物也，然物可兼佔。惜當時君臣見不及此，無有以龜鼠作兼佔者。既佔為鼠，即當雲坎為水為濕，而艮為山為門闕，是必有水中之物，去隱濕而登艮山，可以藏諸室，獻諸闕者，得非龜乎。況之卦之離，顯有龜名，則此中是龜，亦容有之。特吾謂，必是鼠，不是龜者，坎為盜，龜不盜也。噬嗑能囓物，龜不囓物也。震為動為躁決，龜能動不能躁決也。則鼠長耳。使春秋太史而佔物，當必如此。（李恕谷論《仲氏易》）",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
